{"result":"package com.cowave.search.outbound_adapter.proxy

import com.cowave.search.client.proxy_api.ProxyApiClient
import com.cowave.search.client.proxy_api.ProxyApiClientConfig
import com.cowave.search.client.proxy_api.ProxyApiClientProperties
import com.cowave.search.domain.proxy.brand.BrandRepository
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe
import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.boot.test.context.SpringBootTest

@SpringBootTest(
    classes = [
        ProxyApiClientConfig::class,
        ProxyApiClient::class,
        BrandRepositoryImpl::class,
    ]
)
@EnableConfigurationProperties(
    ProxyApiClientProperties::class,
)
class BrandRepositoryImpTest(
    private val repository: BrandRepository
) : FunSpec({
    /**
     * expected response: [{id=27, name=마이다스}, {id=29, name=쥬벨}]
     */
    test("GraphQL get brands query test") {
        val list = repository.findAllByIds(listOf(27, 29))

        list.size shouldBe 2
    }
})"}

